import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium the office charges for a single insured item.
 *
 * The office prices two kinds of item differently. Each main item carries its own listed
 * base premium. Components -- runes, moonstones -- are all priced at one uniform component
 * rate, so a new component type joins the list without a price of its own.
 */
public class PriceList {

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM = 25;

    public boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }

    public int basePremiumFor(Item item) {
        if (isComponent(item)) {
            return COMPONENT_BASE_PREMIUM;
        }
        return MAIN_ITEM_BASE_PREMIUMS.get(item.type());
    }
}
=== ComponentBlockOffer.java ===
import java.util.List;

/**
 * The office's building-block offer: a group of exactly three alike components is
 * charged one special block premium instead of the sum of its components.
 *
 * A group that does not match the offer -- too few or too many components, or main
 * items rather than components -- is charged item by item at the listed price.
 */
public class ComponentBlockOffer {

    private static final int BLOCK_SIZE = 3;
    private static final int BLOCK_BASE_PREMIUM = 60;

    private final PriceList priceList = new PriceList();

    public double basePremiumFor(List<Item> alikeItems) {
        if (formsABlock(alikeItems)) {
            return BLOCK_BASE_PREMIUM;
        }
        return listedPriceOf(alikeItems);
    }

    /**
     * The group is alike by type, so its first item speaks for all of them when the office
     * asks whether it is looking at components.
     */
    private boolean formsABlock(List<Item> alikeItems) {
        return alikeItems.size() == BLOCK_SIZE && priceList.isComponent(alikeItems.get(0));
    }

    private double listedPriceOf(List<Item> items) {
        double total = 0;
        for (Item item : items) {
            total += priceList.basePremiumFor(item);
        }
        return total;
    }
}
=== AlikeItems.java ===
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * What the office considers "alike" when it looks for a building block.
 *
 * The office reads "alike" as items of the same type: three runes are alike, two runes
 * and a moonstone are not. Groups are kept in the order their first item was insured.
 */
public class AlikeItems {

    public Collection<List<Item>> groupsIn(List<Item> items) {
        Map<String, List<Item>> byType = new LinkedHashMap<>();
        for (Item item : items) {
            byType.computeIfAbsent(item.type(), type -> new ArrayList<>()).add(item);
        }
        return byType.values();
    }
}
=== PolicyBasePremium.java ===
import java.util.List;

/**
 * The policy base premium: the sum of the base premiums of all insured items.
 *
 * The office prices alike items as a group, so that the building-block offer can apply
 * to each group in turn; the policy base premium is the sum of those group prices.
 * Risk surcharges for individual items are not part of it -- they attach to the
 * affected item, not to the policy.
 */
public class PolicyBasePremium {

    private final AlikeItems alikeItems = new AlikeItems();
    private final ComponentBlockOffer blockOffer = new ComponentBlockOffer();

    public double forItems(List<Item> items) {
        double total = 0;
        for (List<Item> group : alikeItems.groupsIn(items)) {
            total += blockOffer.basePremiumFor(group);
        }
        return total;
    }
}
=== ItemRiskSurcharge.java ===
/**
 * The risk surcharges the office adds for a single insured item.
 *
 * A cursed item carries a risk surcharge on its own base premium, not on the premium
 * of the whole policy.
 */
public class ItemRiskSurcharge {

    private static final double CURSE_SURCHARGE_RATE = 0.50;

    private final PriceList priceList = new PriceList();

    public double forItem(Item item) {
        if (item.cursed()) {
            return priceList.basePremiumFor(item) * CURSE_SURCHARGE_RATE;
        }
        return 0;
    }
}
=== PolicyRiskSurcharges.java ===
import java.util.List;

/**
 * What the item-specific risk surcharges of a policy add up to.
 *
 * The office assesses each insured item on its own -- a curse raises the premium of the
 * cursed item, not of its harmless neighbours -- and the policy carries the sum.
 */
public class PolicyRiskSurcharges {

    private final ItemRiskSurcharge itemRiskSurcharge = new ItemRiskSurcharge();

    public double forItems(List<Item> items) {
        double total = 0;
        for (Item item : items) {
            total += itemRiskSurcharge.forItem(item);
        }
        return total;
    }
}
